#!/bin/sh
# layer-2 load audit -- swift -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_swift.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_swift
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_swift.txt
: > "$OUT"
echo "=== layer-2 load audit -- swift ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! test -x /persist/swift/usr/bin/swiftc >/dev/null 2>&1; then
  echo "swift: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- nothing.Optional (nil).null
D=$ROOT/p1; mkdir -p "$D"; cd "$D"
cat > main.swift <<'L2_SRC_EOF'

let v: Int64? = nil
print("nothing.Optional (nil).null" + "|" + (v == nil ? "nil" : String(v!)))
L2_SRC_EOF
V=ok
if ! timeout 180 /persist/swift/usr/bin/swiftc main.swift -o prog > build.out 2> build.err; then V="<compile-error>"; fi
if [ "$V" = ok ]; then
  if timeout 30 ./prog > run.out 2> run.err; then :; else
    V="<aborted>"
  fi
  grep -F "nothing.Optional (nil).null|" run.out >> "$OUT" || V="${V}"
fi
grep -qF "nothing.Optional (nil).null|" "$OUT" || echo "nothing.Optional (nil).null|$V" >> "$OUT"

